import { Request, Response } from 'express';
import { exchangeCode, getUserInfo } from './oauth';
import { findOrCreateUser } from '../users/model';
import { createSession } from './session';

export async function handleOAuthCallback(req: Request, res: Response) {
  const { code, state } = req.query;

  if (!code || !state) {
    return res.redirect('/login?error=missing_params');
  }

  try {
    const tokens = await exchangeCode(code as string);
    const userInfo = await getUserInfo(tokens.access_token);
    const user = await findOrCreateUser({
      email: userInfo.email,
      name: userInfo.name,
      provider: 'google',
      providerId: userInfo.sub,
    });
    const session = await createSession(user.id);
    res.cookie('session', session.token, { httpOnly: true, secure: true });
    res.redirect(state as string);
  } catch (err) {
    console.error('OAuth callback error:', err);
    res.redirect('/login?error=auth_failed');
  }
}

import axios from 'axios';

const GOOGLE_TOKEN_URL = 'https://oauth2.googleapis.com/token';
const GOOGLE_USERINFO_URL = 'https://www.googleapis.com/oauth2/v3/userinfo';

export async function exchangeCode(code: string) {
  const response = await axios.post(GOOGLE_TOKEN_URL, {
    code,
    client_id: process.env.GOOGLE_CLIENT_ID,
    client_secret: process.env.GOOGLE_CLIENT_SECRET,
    redirect_uri: process.env.GOOGLE_REDIRECT_URI,
    grant_type: 'authorization_code',
  });
  return response.data;
}

export async function getUserInfo(accessToken: string) {
  const response = await axios.get(GOOGLE_USERINFO_URL, {
    headers: { Authorization: `Bearer ${accessToken}` },
  });
  return response.data;
}

export const OAUTH_CONFIG = {
  clientId: process.env.GOOGLE_CLIENT_ID!,
  clientSecret: process.env.GOOGLE_CLIENT_SECRET!,
  redirectUri: process.env.GOOGLE_REDIRECT_URI || 'http://localhost:3000/auth/callback',
  scopes: ['openid', 'profile', 'email'],
};

