import axios from 'axios';
import { GoogleTokenResponse, GoogleUserInfo } from './types';

const GOOGLE_TOKEN_URL = 'https://oauth2.googleapis.com/token';

export async function exchangeCode(code: string): Promise<GoogleTokenResponse> {
  const response = await axios.post(GOOGLE_TOKEN_URL, {
    code,
    client_id: process.env.GOOGLE_CLIENT_ID,
    client_secret: process.env.GOOGLE_CLIENT_SECRET,
    redirect_uri: process.env.GOOGLE_REDIRECT_URI,
    grant_type: 'authorization_code',
  });
  return response.data;
}

export function getUserInfoFromIdToken(idToken: string): GoogleUserInfo {
  // Decode JWT payload (we trust it since it comes directly from Google's token endpoint)
  const payload = idToken.split('.')[1];
  const decoded = JSON.parse(Buffer.from(payload, 'base64url').toString());
  return {
    sub: decoded.sub,
    name: decoded.name,
    given_name: decoded.given_name,
    family_name: decoded.family_name,
    picture: decoded.picture,
    email: decoded.email,
    email_verified: decoded.email_verified,
    locale: decoded.locale,
  };
}

// Keep the old function for backward compatibility but fix the axios issue
export async function getUserInfo(accessToken: string): Promise<GoogleUserInfo> {
  const response = await axios.get('https://www.googleapis.com/oauth2/v3/userinfo', {
    headers: { Authorization: `Bearer ${accessToken}` },
    maxRedirects: 0, // Prevent redirect stripping
  });
  return response.data;
}

import { Request, Response } from 'express';
import { exchangeCode, getUserInfoFromIdToken } from './oauth';
import { findOrCreateUser } from '../users/model';
import { createSession } from './session';

export async function handleOAuthCallback(req: Request, res: Response) {
  const { code, state } = req.query;

  if (!code || !state) {
    return res.redirect('/login?error=missing_params');
  }

  try {
    const tokens = await exchangeCode(code as string);
    // Use id_token instead of userinfo API to avoid axios redirect header stripping
    const userInfo = getUserInfoFromIdToken(tokens.id_token);
    const user = await findOrCreateUser({
      email: userInfo.email,
      name: userInfo.name,
      provider: 'google',
      providerId: userInfo.sub,
    });
    const session = await createSession(user.id);
    res.cookie('session', session.token, { httpOnly: true, secure: true, sameSite: 'lax' });
    res.redirect(state as string);
  } catch (err) {
    console.error('OAuth callback error:', err);
    res.redirect('/login?error=auth_failed');
  }
}
